output_probe_argv:
identity=$(gh repo view "$2" --json nameWithOwner,url --jq '(.url | split("/")[2]), .nameWithOwner') || exit 1
host=${identity%%
*}
repo=${identity#*
}
pages=$(gh api graphql --hostname "$host" --paginate --slurp -F owner="${repo%/*}" -F name="${repo##*/}" -F pr="$1" -f query="$4") || exit 1
out=$(printf '%s\n' "$pages" | jq -rc "$5$3)") || exit 1
head=${out%%
*}
current=$(gh pr view "$1" --repo "$2" --json headRefOid --jq .headRefOid) || exit 1
[ "$head" = "$current" ] || exit 1
printf '%s\n' "${out#*
}"
